-- Understanding the Holy Spirit (10 sessions)
insert into public.p2p_study_plans (slug, title, description, focus_type, focus_ref, focus_label, plan_kind, collection, derived_from, origin, editorial_status, objectives, suggested_pace, suggested_days)
values ('understanding-the-holy-spirit', 'Understanding the Holy Spirit', 'Follow what Scripture says about the Holy Spirit — from creation and the prophets, through Jesus'' promise and Pentecost, to the Spirit''s work in believers and the church.', 'theme', '{"theme":"holy-spirit"}'::jsonb, 'The Holy Spirit', 'scripture', 'topical', null, 'p2p', 'draft', '["See how the Holy Spirit is described across the Old and New Testaments","Understand Jesus'' promise of the Spirit and its fulfilment at Pentecost","Consider the Spirit''s work in believers and in the church"]'::jsonb, 'five_weekly', 14)
on conflict (slug) where slug is not null do nothing;
insert into public.p2p_study_plan_sessions (plan_id, position, title, intro, passages, supporting, questions)
select pl.id, s.position, s.title, s.intro, s.passages, s.supporting, s.questions
from public.p2p_study_plans pl, (values
  (1, 'The Spirit at creation and in Israel', 'The Spirit appears in Scripture''s first verses, and later comes upon the elders who help Moses lead.', '[{"book":"GEN","chapter":1,"startVerse":1,"endVerse":2},{"book":"NUM","chapter":11,"startVerse":16,"endVerse":17},{"book":"NUM","chapter":11,"startVerse":24,"endVerse":29}]'::jsonb, '[{"kind":"word_study","strongs":"H7307","note":"ruach, ''spirit, breath, wind''"}]'::jsonb, '[{"kind":"observe","text":"What is the Spirit of God doing in Genesis 1:2?"},{"kind":"context","text":"In Numbers 11, why does Moses need help, and what happens when the Spirit comes on the seventy elders?"},{"kind":"interpret","text":"What does Moses'' wish in Numbers 11:29 suggest about how widely the Spirit might one day be given?"}]'::jsonb),
  (2, 'The promise through the prophets', 'The prophets look forward to a day when God will put his Spirit within his people and pour it out on all kinds of people.', '[{"book":"EZK","chapter":36,"startVerse":24,"endVerse":28},{"book":"JOL","chapter":2,"startVerse":28,"endVerse":29}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What does God promise to do in Ezekiel 36:26-27?"},{"kind":"interpret","text":"In Joel 2:28-29, who receives the Spirit? What is significant about that list?"},{"kind":"context","text":"These promises were given to Israel in times of exile and judgement. What hope do they hold out?"}]'::jsonb),
  (3, 'The Spirit and Jesus', 'The Spirit descends on Jesus at his baptism, leads him into the wilderness, and Jesus announces his mission in the Spirit''s power.', '[{"book":"LUK","chapter":3,"startVerse":21,"endVerse":22},{"book":"LUK","chapter":4,"startVerse":1,"endVerse":2},{"book":"LUK","chapter":4,"startVerse":14,"endVerse":21}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What happens at Jesus'' baptism in Luke 3:21-22?"},{"kind":"observe","text":"How often is the Spirit mentioned in Luke 4:1-18? What does that emphasise?"},{"kind":"interpret","text":"In Luke 4:18-19, Jesus reads from Isaiah. What does the Spirit anoint him to do?"}]'::jsonb),
  (4, 'Born of the Spirit', 'Jesus tells Nicodemus, a teacher of Israel, that no one can see the kingdom of God unless they are born again.', '[{"book":"JHN","chapter":3,"startVerse":1,"endVerse":8}]'::jsonb, '[{"kind":"deep_study","book":"JHN","chapter":3,"startVerse":3,"endVerse":8,"note":"''Born again / from above'' in the original"}]'::jsonb, '[{"kind":"context","text":"Who is Nicodemus, and when does he come to Jesus?"},{"kind":"interpret","text":"What does Jesus mean by being ''born of water and the Spirit'' (verse 5)? What do the following verses add?"},{"kind":"interpret","text":"What does the comparison with the wind in verse 8 suggest about the Spirit''s work?"}]'::jsonb),
  (5, 'Another Helper', 'On the night before his death, Jesus promises his disciples that the Father will send the Spirit.', '[{"book":"JHN","chapter":14,"startVerse":15,"endVerse":26},{"book":"JHN","chapter":16,"startVerse":7,"endVerse":15}]'::jsonb, '[{"kind":"word_study","strongs":"G3875","note":"paraklētos, ''helper, advocate''"}]'::jsonb, '[{"kind":"observe","text":"What names and descriptions does Jesus use for the Spirit in these passages?"},{"kind":"observe","text":"List what Jesus says the Spirit will do in John 14:26 and 16:8-15."},{"kind":"interpret","text":"Why does Jesus say in 16:7 that it is good for the disciples that he goes away?"}]'::jsonb),
  (6, 'Pentecost', 'Fifty days after the resurrection, the Spirit is poured out on the disciples in Jerusalem, and Peter explains what is happening.', '[{"book":"ACT","chapter":2,"startVerse":1,"endVerse":21},{"book":"ACT","chapter":2,"startVerse":37,"endVerse":41}]'::jsonb, '[{"kind":"commentary","book":"ACT","chapter":2,"note":"Commentary on Acts 2"}]'::jsonb, '[{"kind":"observe","text":"Describe what happens in Acts 2:1-4 and how the crowd reacts."},{"kind":"context","text":"Which prophecy does Peter quote in verses 16-21, and how does it connect with what you read in Joel?"},{"kind":"observe","text":"What does Peter tell the crowd to do in verse 38, and what does he promise?"}]'::jsonb),
  (7, 'Life by the Spirit', 'Paul describes believers as people in whom the Spirit of God lives, led by the Spirit as God''s children.', '[{"book":"ROM","chapter":8,"startVerse":9,"endVerse":17}]'::jsonb, '[]'::jsonb, '[{"kind":"interpret","text":"According to verses 9-11, what difference does the Spirit''s presence make?"},{"kind":"observe","text":"What does the Spirit enable believers to call God in verse 15?"},{"kind":"interpret","text":"What does verse 16 say the Spirit testifies to?"}]'::jsonb),
  (8, 'The fruit of the Spirit', 'Paul contrasts the works of the flesh with the fruit the Spirit produces.', '[{"book":"GAL","chapter":5,"startVerse":16,"endVerse":26}]'::jsonb, '[{"kind":"word_study","strongs":"G2590","note":"karpos, ''fruit''"}]'::jsonb, '[{"kind":"observe","text":"What does Paul tell the Galatians to do in verses 16 and 25?"},{"kind":"interpret","text":"Paul speaks of the ''fruit'' (singular) of the Spirit in verses 22-23. What might that word suggest about how these qualities grow?"},{"kind":"consider","text":"Which quality in verses 22-23 would you most like to understand better, and why?"}]'::jsonb),
  (9, 'Gifts for the common good', 'Writing to a divided church, Paul explains that the Spirit gives different gifts to different people for the good of all.', '[{"book":"1CO","chapter":12,"startVerse":1,"endVerse":13}]'::jsonb, '[{"kind":"scripture_topic","slug":"the-church"},{"kind":"scripture_topic","slug":"unity"}]'::jsonb, '[{"kind":"context","text":"What was happening in the Corinthian church that led Paul to write about spiritual gifts?"},{"kind":"observe","text":"Who gives the gifts, and for what purpose (verses 4-7, 11)?"},{"kind":"interpret","text":"What does the picture of one body in verses 12-13 teach about believers'' different gifts?"}]'::jsonb),
  (10, 'Sealed and filled', 'Paul describes the Spirit as God''s seal and guarantee, warns against grieving the Spirit, and urges believers to be filled with the Spirit.', '[{"book":"EPH","chapter":1,"startVerse":13,"endVerse":14},{"book":"EPH","chapter":4,"startVerse":30,"endVerse":30},{"book":"EPH","chapter":5,"startVerse":15,"endVerse":20}]'::jsonb, '[]'::jsonb, '[{"kind":"interpret","text":"What do the words ''seal'' and ''deposit'' or ''guarantee'' (1:13-14) suggest about the Spirit''s role?"},{"kind":"observe","text":"What does Paul say not to do in 4:30, and what surrounds that verse in 4:25-32?"},{"kind":"observe","text":"What does being filled with the Spirit look like in 5:18-20?"}]'::jsonb)
) as s(position, title, intro, passages, supporting, questions)
where pl.slug = 'understanding-the-holy-spirit' and not exists (select 1 from public.p2p_study_plan_sessions x where x.plan_id = pl.id);

-- Kingdom School Foundations (sessions = the real lessons, read live)
insert into public.p2p_study_plans (slug, title, description, focus_type, focus_ref, focus_label, plan_kind, collection, derived_from, origin, editorial_status, objectives, suggested_pace, suggested_days)
values ('kingdom-school-foundations', 'Kingdom School Foundations', 'Follow every Kingdom School Foundations lesson in curriculum order at a pace you choose. The lessons, their order and their assessments are exactly those of Kingdom School; this plan only helps you schedule them.', 'core_foundations', '{}'::jsonb, 'Kingdom School Foundations', 'structured', 'core_foundations', '{"type":"foundations"}'::jsonb, 'p2p', 'draft', '["Work through every Foundations lesson in order","Complete each lesson''s assessment through Kingdom School as usual"]'::jsonb, 'five_weekly', 182)
on conflict (slug) where slug is not null do nothing;

-- The Life of Jesus (12 sessions)
insert into public.p2p_study_plans (slug, title, description, focus_type, focus_ref, focus_label, plan_kind, collection, derived_from, origin, editorial_status, objectives, suggested_pace, suggested_days)
values ('the-life-of-jesus', 'The Life of Jesus', 'Walk through the life and teaching of Jesus Christ in the Gospels, from his birth to his resurrection and commission to his followers.', 'biblical_person', '{"person":"jesus"}'::jsonb, 'Jesus Christ', 'scripture', 'life_of_jesus', null, 'p2p', 'draft', '["Read the main events of Jesus'' life in the Gospels","Notice what Jesus taught and how people responded to him","Consider who Jesus says he is"]'::jsonb, 'daily', 12)
on conflict (slug) where slug is not null do nothing;
insert into public.p2p_study_plan_sessions (plan_id, position, title, intro, passages, supporting, questions)
select pl.id, s.position, s.title, s.intro, s.passages, s.supporting, s.questions
from public.p2p_study_plans pl, (values
  (1, 'The Word became flesh', 'John opens his Gospel before Bethlehem — with the eternal Word who was with God and was God.', '[{"book":"JHN","chapter":1,"startVerse":1,"endVerse":18}]'::jsonb, '[{"kind":"word_study","strongs":"G3056","note":"logos, ''word''"}]'::jsonb, '[{"kind":"observe","text":"What does John say about the Word in verses 1-5?"},{"kind":"interpret","text":"What does verse 14 say happened, and why is that remarkable after verses 1-3?"},{"kind":"observe","text":"According to verses 11-13, how did people respond to him, and what is given to those who received him?"}]'::jsonb),
  (2, 'The birth of Jesus', 'Luke places Jesus'' birth in history — the reign of Caesar Augustus — and tells of shepherds who hear the news first.', '[{"book":"LUK","chapter":2,"startVerse":1,"endVerse":20}]'::jsonb, '[]'::jsonb, '[{"kind":"context","text":"Why were Joseph and Mary in Bethlehem (verses 1-5)?"},{"kind":"observe","text":"What do the angels announce to the shepherds in verses 10-14?"},{"kind":"observe","text":"How do the shepherds and Mary respond in verses 15-20?"}]'::jsonb),
  (3, 'Baptism and temptation', 'Before his public ministry begins, Jesus is baptised by John and tested in the wilderness.', '[{"book":"MAT","chapter":3,"startVerse":13,"endVerse":17},{"book":"MAT","chapter":4,"startVerse":1,"endVerse":11}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What does the voice from heaven say in Matthew 3:17?"},{"kind":"observe","text":"How does Jesus answer each temptation in Matthew 4:1-11?"},{"kind":"context","text":"Jesus'' answers come from Deuteronomy, from Israel''s time in the wilderness. What connection might Matthew be drawing?"}]'::jsonb),
  (4, 'Calling the first disciples', 'Jesus begins to proclaim the good news of God''s kingdom, calls fishermen to follow him, and heals many.', '[{"book":"MRK","chapter":1,"startVerse":14,"endVerse":20},{"book":"MRK","chapter":1,"startVerse":29,"endVerse":39}]'::jsonb, '[{"kind":"scripture_topic","slug":"discipleship"}]'::jsonb, '[{"kind":"observe","text":"What message does Jesus proclaim in Mark 1:14-15?"},{"kind":"observe","text":"What does Jesus ask Simon, Andrew, James and John to do, and how do they respond?"},{"kind":"interpret","text":"Why do you think Jesus leaves the crowds to pray and move on (verses 35-39)?"}]'::jsonb),
  (5, 'The Sermon on the Mount', 'Jesus teaches his disciples about the blessed life in God''s kingdom and their place in the world.', '[{"book":"MAT","chapter":5,"startVerse":1,"endVerse":16}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"Who does Jesus call ''blessed'' in verses 3-10?"},{"kind":"interpret","text":"What do the pictures of salt and light (verses 13-16) say about the disciples'' role?"},{"kind":"consider","text":"Which of the beatitudes surprises you most, and why?"}]'::jsonb),
  (6, 'Who is this?', 'Jesus calms a storm and sets free a man no one could restrain. Both events raise the question of who Jesus is.', '[{"book":"MRK","chapter":4,"startVerse":35,"endVerse":41},{"book":"MRK","chapter":5,"startVerse":1,"endVerse":20}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What question do the disciples ask at the end of Mark 4:41?"},{"kind":"observe","text":"How is the man described before and after he meets Jesus in Mark 5?"},{"kind":"interpret","text":"What does Jesus tell the man to do in Mark 5:19, and what does he do?"}]'::jsonb),
  (7, 'Parables of the lost', 'When religious leaders grumble that Jesus welcomes sinners, he tells three stories about something lost and found.', '[{"book":"LUK","chapter":15,"startVerse":1,"endVerse":32}]'::jsonb, '[{"kind":"scripture_topic","slug":"forgiveness"}]'::jsonb, '[{"kind":"context","text":"Who is Jesus speaking to, and why does he tell these parables (verses 1-3)?"},{"kind":"observe","text":"What do the three parables have in common?"},{"kind":"interpret","text":"How does the older brother respond in verses 25-32, and who might he represent in the setting of verses 1-2?"}]'::jsonb),
  (8, 'Peter''s confession', 'At Caesarea Philippi, Jesus asks his disciples who they say he is, and then begins to speak of his coming death.', '[{"book":"MAT","chapter":16,"startVerse":13,"endVerse":28}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What answers do people give about Jesus, and what does Peter say (verses 13-16)?"},{"kind":"observe","text":"What does Jesus begin to explain in verse 21, and how does Peter react?"},{"kind":"interpret","text":"What does Jesus say following him involves in verses 24-26?"}]'::jsonb),
  (9, 'Entering Jerusalem', 'Jesus rides into Jerusalem on a colt, the crowds praise him, and he weeps over the city.', '[{"book":"LUK","chapter":19,"startVerse":28,"endVerse":44}]'::jsonb, '[{"kind":"bible_passage","book":"ZEC","chapter":9,"startVerse":9,"endVerse":9,"note":"The prophecy behind the colt"}]'::jsonb, '[{"kind":"context","text":"Read Zechariah 9:9. What would the crowds have understood from Jesus riding a colt into Jerusalem?"},{"kind":"observe","text":"What do the disciples shout in verse 38?"},{"kind":"observe","text":"Why does Jesus weep over Jerusalem (verses 41-44)?"}]'::jsonb),
  (10, 'The last supper and the garden', 'Jesus shares the Passover meal with his disciples and then prays on the Mount of Olives.', '[{"book":"LUK","chapter":22,"startVerse":14,"endVerse":23},{"book":"LUK","chapter":22,"startVerse":39,"endVerse":46}]'::jsonb, '[]'::jsonb, '[{"kind":"context","text":"The meal is the Passover. What did the Passover remember, and how does Jesus give new meaning to the bread and cup?"},{"kind":"observe","text":"What does Jesus pray in verse 42?"},{"kind":"observe","text":"What does Jesus tell his disciples to pray for in verses 40 and 46?"}]'::jsonb),
  (11, 'The cross', 'Jesus is crucified between two criminals. Luke records his words from the cross and the responses of those around him.', '[{"book":"LUK","chapter":23,"startVerse":32,"endVerse":49}]'::jsonb, '[{"kind":"scripture_topic","slug":"salvation"}]'::jsonb, '[{"kind":"observe","text":"What does Jesus say from the cross in verses 34, 43 and 46?"},{"kind":"observe","text":"How do the different people around the cross respond to him?"},{"kind":"interpret","text":"What does the conversation with the second criminal (verses 39-43) show?"}]'::jsonb),
  (12, 'He is risen', 'The women find the tomb empty; later Jesus appears to his disciples, opens the Scriptures to them and sends them out.', '[{"book":"LUK","chapter":24,"startVerse":1,"endVerse":12},{"book":"LUK","chapter":24,"startVerse":36,"endVerse":49}]'::jsonb, '[{"kind":"scripture_topic","slug":"hope"}]'::jsonb, '[{"kind":"observe","text":"What do the angels say to the women in verses 5-7?"},{"kind":"observe","text":"How does Jesus show the disciples that he is really alive (verses 36-43)?"},{"kind":"interpret","text":"According to verses 44-49, what does Jesus say the Scriptures were pointing to, and what will his followers do?"}]'::jsonb)
) as s(position, title, intro, passages, supporting, questions)
where pl.slug = 'the-life-of-jesus' and not exists (select 1 from public.p2p_study_plan_sessions x where x.plan_id = pl.id);

-- The Book of Romans (16 sessions)
insert into public.p2p_study_plans (slug, title, description, focus_type, focus_ref, focus_label, plan_kind, collection, derived_from, origin, editorial_status, objectives, suggested_pace, suggested_days)
values ('romans-16-sessions', 'The Book of Romans', 'Read Paul''s letter to the church in Rome one chapter at a time: the gospel of God''s righteousness, received by faith, and the life it creates.', 'bible_book', '{"book":"ROM"}'::jsonb, 'Romans', 'scripture', 'bible_books', null, 'p2p', 'draft', '["Follow the argument of Romans from beginning to end","Understand what Paul means by righteousness, faith and grace","See how the gospel shapes everyday life and the church"]'::jsonb, 'daily', 16)
on conflict (slug) where slug is not null do nothing;
insert into public.p2p_study_plan_sessions (plan_id, position, title, intro, passages, supporting, questions)
select pl.id, s.position, s.title, s.intro, s.passages, s.supporting, s.questions
from public.p2p_study_plans pl, (values
  (1, 'The gospel of God', 'Paul introduces himself to a church he has not yet visited and states the theme of the letter (1:16-17) before describing humanity''s turning away from God.', '[{"book":"ROM","chapter":1,"startVerse":1,"endVerse":32}]'::jsonb, '[{"kind":"word_study","strongs":"G2098","note":"euangelion, ''good news''"},{"kind":"deep_study","book":"ROM","chapter":1,"startVerse":16,"endVerse":17,"note":"The letter''s theme in the original language"}]'::jsonb, '[{"kind":"observe","text":"How does Paul describe himself and the gospel in verses 1-6?"},{"kind":"interpret","text":"According to verses 16-17, what is revealed in the gospel, and how is it received?"},{"kind":"context","text":"In verses 18-32, what does Paul say people did with what they knew about God?"},{"kind":"consider","text":"Paul says he is ''not ashamed of the gospel''. What does that phrase suggest about how the gospel was viewed?"}]'::jsonb),
  (2, 'God judges impartially', 'Paul turns to those who judge others, and then to his own people, showing that knowing God''s law does not place anyone beyond God''s judgement.', '[{"book":"ROM","chapter":2,"startVerse":1,"endVerse":29}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What warning does Paul give in verses 1-4 to the person who judges others?"},{"kind":"interpret","text":"What does verse 11 say about God, and how does the rest of the chapter illustrate it?"},{"kind":"context","text":"Who is Paul addressing from verse 17 onwards, and what are they relying on?"},{"kind":"interpret","text":"What does Paul mean by circumcision ''of the heart, by the Spirit'' (verse 29)?"}]'::jsonb),
  (3, 'Righteousness through faith', 'Paul concludes that all people, Jew and Gentile, are under sin, and then announces ''but now'' — God''s righteousness given through faith in Jesus Christ.', '[{"book":"ROM","chapter":3,"startVerse":1,"endVerse":31}]'::jsonb, '[{"kind":"word_study","strongs":"G1344","note":"dikaioō, ''to justify''"},{"kind":"scripture_topic","slug":"grace","note":"Grace across Scripture"}]'::jsonb, '[{"kind":"observe","text":"What conclusion does Paul reach in verses 9-20?"},{"kind":"interpret","text":"In verses 21-26, how is God''s righteousness made known, and to whom is it given?"},{"kind":"interpret","text":"Verse 26 says God is both ''just'' and ''the justifier''. How does the death of Jesus make both true?"},{"kind":"consider","text":"What does verse 27 say happens to boasting, and why?"}]'::jsonb),
  (4, 'Abraham believed God', 'Paul shows from Genesis that Abraham was counted righteous through faith, before circumcision and apart from the law.', '[{"book":"ROM","chapter":4,"startVerse":1,"endVerse":25}]'::jsonb, '[{"kind":"bible_passage","book":"GEN","chapter":15,"startVerse":1,"endVerse":6,"note":"The promise Paul quotes"}]'::jsonb, '[{"kind":"context","text":"Why does Paul turn to Abraham at this point in his argument?"},{"kind":"observe","text":"According to verses 9-12, when was Abraham counted righteous — before or after circumcision? Why does that matter?"},{"kind":"interpret","text":"How do verses 18-21 describe Abraham''s faith?"},{"kind":"consider","text":"Verses 23-25 say these words were written ''for us also''. What connects Abraham''s faith with faith in Jesus?"}]'::jsonb),
  (5, 'Peace with God', 'Paul describes what justification brings — peace, access, hope — and then compares Adam and Christ.', '[{"book":"ROM","chapter":5,"startVerse":1,"endVerse":21}]'::jsonb, '[{"kind":"scripture_topic","slug":"hope","note":"Hope across Scripture"},{"kind":"scripture_topic","slug":"peace"}]'::jsonb, '[{"kind":"observe","text":"List what verses 1-5 say believers now have through Jesus."},{"kind":"interpret","text":"What does verse 8 show about God''s love, and when was it shown?"},{"kind":"interpret","text":"In verses 12-21, what came through Adam, and what came through Christ?"},{"kind":"consider","text":"Paul links suffering with hope in verses 3-5. How does he describe that process?"}]'::jsonb),
  (6, 'Dead to sin, alive to God', 'Paul answers an objection: if grace abounds, should we keep sinning? He explains what union with Christ in his death and resurrection means.', '[{"book":"ROM","chapter":6,"startVerse":1,"endVerse":23}]'::jsonb, '[{"kind":"scripture_topic","slug":"freedom","note":"Freedom across Scripture"}]'::jsonb, '[{"kind":"context","text":"What question is Paul answering in verse 1, and why might someone ask it after chapter 5?"},{"kind":"interpret","text":"What does baptism picture in verses 3-5?"},{"kind":"observe","text":"What does Paul tell believers to ''count'' or ''consider'' in verse 11?"},{"kind":"interpret","text":"Compare the ''wages'' and the ''gift'' in verse 23. What is the difference between them?"}]'::jsonb),
  (7, 'The law and the struggle with sin', 'Paul explains the believer''s release from the law and describes, in the first person, the inner conflict between knowing what is good and doing it.', '[{"book":"ROM","chapter":7,"startVerse":1,"endVerse":25}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What illustration does Paul use in verses 1-4, and what point does it make?"},{"kind":"interpret","text":"According to verses 7-12, is the law itself sinful? What does Paul say the law does?"},{"kind":"context","text":"Christians have read verses 14-25 in different ways (Paul before or after faith in Christ). What details in the passage do readers point to?"},{"kind":"observe","text":"How does the chapter end (verses 24-25), and where does Paul look for rescue?"}]'::jsonb),
  (8, 'Life in the Spirit', 'There is now no condemnation for those in Christ Jesus. Paul describes the Spirit''s work, the hope of creation and the love of God that nothing can separate us from.', '[{"book":"ROM","chapter":8,"startVerse":1,"endVerse":39}]'::jsonb, '[{"kind":"word_study","strongs":"G4151","note":"pneuma, ''Spirit''"},{"kind":"scripture_topic","slug":"identity-in-christ"}]'::jsonb, '[{"kind":"observe","text":"What does verse 1 declare, and what reason do verses 2-4 give for it?"},{"kind":"interpret","text":"What does the Spirit do for believers according to verses 14-17 and 26-27?"},{"kind":"context","text":"In verses 18-25, what is creation waiting for?"},{"kind":"observe","text":"Make a list of the things in verses 35-39 that cannot separate believers from God''s love."}]'::jsonb),
  (9, 'God''s purposes and Israel', 'Paul expresses deep grief for his own people and begins three chapters on how God''s promises to Israel stand.', '[{"book":"ROM","chapter":9,"startVerse":1,"endVerse":33}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"How does Paul describe his feelings for Israel in verses 1-5?"},{"kind":"context","text":"What question lies behind verse 6 (''it is not as though the word of God has failed'')?"},{"kind":"interpret","text":"What examples from Israel''s history does Paul use in verses 6-18, and what do they show about God''s mercy?"},{"kind":"observe","text":"According to verses 30-32, how did Gentiles obtain righteousness, and why did Israel not obtain it?"}]'::jsonb),
  (10, 'Everyone who calls on the Lord', 'Paul explains that righteousness comes by faith, and that the message must be heard and proclaimed.', '[{"book":"ROM","chapter":10,"startVerse":1,"endVerse":21}]'::jsonb, '[{"kind":"scripture_topic","slug":"salvation"},{"kind":"scripture_topic","slug":"evangelism"}]'::jsonb, '[{"kind":"observe","text":"What does Paul pray for in verse 1?"},{"kind":"interpret","text":"According to verses 9-10, what is involved in being saved?"},{"kind":"observe","text":"Trace the chain of questions in verses 14-15. What is needed for people to call on the Lord?"},{"kind":"consider","text":"Verse 12 says there is ''no difference'' between Jew and Greek. What is the basis for that?"}]'::jsonb),
  (11, 'The olive tree and God''s mercy', 'Paul insists God has not rejected his people, uses the image of an olive tree, and ends in praise.', '[{"book":"ROM","chapter":11,"startVerse":1,"endVerse":36}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"What evidence does Paul give in verses 1-6 that God has not rejected his people?"},{"kind":"interpret","text":"What does the olive tree illustration (verses 17-24) teach Gentile believers?"},{"kind":"context","text":"What warning against pride does Paul give in verses 18-22?"},{"kind":"observe","text":"How do verses 33-36 respond to everything Paul has explained in chapters 9-11?"}]'::jsonb),
  (12, 'A living sacrifice', '''Therefore'' — after eleven chapters about God''s mercy, Paul describes the life that responds to it, in the body of Christ and toward everyone.', '[{"book":"ROM","chapter":12,"startVerse":1,"endVerse":21}]'::jsonb, '[{"kind":"scripture_topic","slug":"the-church"},{"kind":"scripture_topic","slug":"love"}]'::jsonb, '[{"kind":"context","text":"Verse 1 begins with ''therefore'' and ''in view of God''s mercy''. What has Paul shown about God''s mercy in the earlier chapters?"},{"kind":"interpret","text":"What does it mean to be transformed ''by the renewing of your mind'' (verse 2)?"},{"kind":"observe","text":"What picture of the church does Paul use in verses 4-8?"},{"kind":"apply","text":"Verses 17-21 describe how to respond to evil. Which of these instructions stands out to you, and why?"}]'::jsonb),
  (13, 'Authorities, love and the day ahead', 'Paul writes about governing authorities, sums up the commandments in love, and urges readiness because the day is near.', '[{"book":"ROM","chapter":13,"startVerse":1,"endVerse":14}]'::jsonb, '[]'::jsonb, '[{"kind":"context","text":"Paul wrote this under Roman rule. What does he say about the purpose of governing authorities in verses 1-7?"},{"kind":"interpret","text":"According to verses 8-10, how does love fulfil the law?"},{"kind":"observe","text":"What does Paul say about time in verses 11-12?"},{"kind":"interpret","text":"What does it mean to ''clothe yourselves with the Lord Jesus Christ'' (verse 14)?"}]'::jsonb),
  (14, 'Welcoming one another', 'Paul addresses disagreements in the church over food and special days, and how believers with different convictions should treat each other.', '[{"book":"ROM","chapter":14,"startVerse":1,"endVerse":23}]'::jsonb, '[{"kind":"scripture_topic","slug":"unity"}]'::jsonb, '[{"kind":"context","text":"What were the believers in Rome disagreeing about in verses 2-6?"},{"kind":"observe","text":"Why, according to verses 7-12, should believers not judge one another on these matters?"},{"kind":"interpret","text":"What does Paul say the kingdom of God is (and is not) in verse 17?"},{"kind":"apply","text":"Verse 19 says to pursue what leads to peace and building one another up. What might that look like where you are?"}]'::jsonb),
  (15, 'Christ''s welcome and Paul''s mission', 'Paul points to Christ''s example of welcoming others, then shares his travel plans and asks for prayer.', '[{"book":"ROM","chapter":15,"startVerse":1,"endVerse":33}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"Whose example does Paul point to in verses 3 and 7?"},{"kind":"interpret","text":"What do the Old Testament quotations in verses 9-12 have in common?"},{"kind":"context","text":"What are Paul''s plans in verses 22-29, and what is the collection for Jerusalem?"},{"kind":"observe","text":"What does Paul ask the Romans to pray for in verses 30-32?"}]'::jsonb),
  (16, 'Greetings and a final doxology', 'Paul greets many people by name, warns against those who cause division, and closes in praise to God.', '[{"book":"ROM","chapter":16,"startVerse":1,"endVerse":27}]'::jsonb, '[]'::jsonb, '[{"kind":"observe","text":"Look through the names in verses 1-16. What do you notice about the people Paul greets and how he describes them?"},{"kind":"observe","text":"What warning does Paul give in verses 17-20?"},{"kind":"interpret","text":"What does the final doxology (verses 25-27) say about the gospel and its purpose?"},{"kind":"consider","text":"Looking back over the whole letter, what has Romans shown you about the gospel?"}]'::jsonb)
) as s(position, title, intro, passages, supporting, questions)
where pl.slug = 'romans-16-sessions' and not exists (select 1 from public.p2p_study_plan_sessions x where x.plan_id = pl.id);

commit;
